using System;

namespace Misty.Tokens;

/// <summary>Light or dark appearance.</summary>
public enum MistyAppearance { Light, Dark }

/// <summary>The translucent grades of glass. Cloud is solid: use the Cloud colour.</summary>
public enum MistyGlassGrade { Clear, Mist, Veil }

/// <summary>The five window classes, measured on the window's width.</summary>
public enum MistyWindowClass { Narrow, Compact, Medium, Expanded, Wide }

/// <summary>An sRGB colour with 8-bit channels. On WinUI 3, pass the channels to
/// Microsoft.UI.ColorHelper.FromArgb.</summary>
public readonly record struct MistyRgba(byte A, byte R, byte G, byte B)
{
    /// <summary>The colour as #AARRGGBB, as XAML expects.</summary>
    public string ToHex() => $"#{A:X2}{R:X2}{G:X2}{B:X2}";
}

/// <summary>An OKLCH colour. When FollowsHue is true, H is an offset from the Misty hue.</summary>
public readonly record struct MistyOklch(double L, double C, double H, double Alpha, bool FollowsHue)
{
    /// <summary>sRGB, clipped per channel as browsers do on sRGB displays.</summary>
    public MistyRgba Resolve(double hue)
    {
        double angle = (FollowsHue ? hue + H : H) * Math.PI / 180.0;
        double a = C * Math.Cos(angle);
        double b = C * Math.Sin(angle);
        double l3 = Math.Pow(L + 0.3963377774 * a + 0.2158037573 * b, 3);
        double m3 = Math.Pow(L - 0.1055613458 * a - 0.0638541728 * b, 3);
        double s3 = Math.Pow(L - 0.0894841775 * a - 1.2914855480 * b, 3);
        return new MistyRgba(
            (byte)Math.Round(Alpha * 255, MidpointRounding.AwayFromZero),
            Encode(4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3),
            Encode(-1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3),
            Encode(-0.0041960863 * l3 - 0.7034186147 * m3 + 1.7076147010 * s3));
    }

    private static byte Encode(double v)
    {
        double g = v <= 0.0031308 ? 12.92 * v : 1.055 * Math.Pow(v, 1 / 2.4) - 0.055;
        return (byte)Math.Round(Math.Clamp(g, 0.0, 1.0) * 255, MidpointRounding.AwayFromZero);
    }
}

/// <summary>A colour token with a light and a dark value.</summary>
public readonly record struct MistyThemedColor(MistyOklch Light, MistyOklch Dark)
{
    public MistyRgba Resolve(double hue, MistyAppearance appearance) =>
        (appearance == MistyAppearance.Dark ? Dark : Light).Resolve(hue);
}

/// <summary>One layer of an elevation shadow, in effective pixels.</summary>
public readonly record struct MistyShadowLayer(double X, double Y, double Blur, double Spread, MistyOklch Color);

