/// <summary>Glass: a tint of the field at a grade's alpha. WinUI's acrylic has a fixed blur;
/// set its tint to the fill and its tint opacity to the alpha (PLT-05).</summary>
public static class MistyGlass
{
    public const double Lightness = 0.995;
    public const double LightnessDark = 0.215;
    public const double Chroma = 0.004;
    public const double ChromaDark = 0.02;
    public const double Saturation = 1.75;

    public static double Alpha(MistyGlassGrade grade, MistyAppearance appearance)
    {
        bool dark = appearance == MistyAppearance.Dark;
        return grade switch
        {
            MistyGlassGrade.Clear => dark ? 0.36 : 0.3,
            MistyGlassGrade.Mist => dark ? 0.5 : 0.42,
            MistyGlassGrade.Veil => dark ? 0.68 : 0.62,
            _ => 1.0,
        };
    }

    /// <summary>The blur's standard deviation in effective pixels, as in CSS.</summary>
    public static double Blur(MistyGlassGrade grade) => grade switch
    {
        MistyGlassGrade.Clear => 24.0,
        MistyGlassGrade.Mist => 26.0,
        MistyGlassGrade.Veil => 32.0,
        _ => 0.0,
    };
}

/// <summary>Resolves Misty's colours for one hue and appearance.</summary>
public sealed class MistyTheme
{
    public MistyTheme(double hue = 250.0, MistyAppearance appearance = MistyAppearance.Light)
    {
        Hue = hue;
        Appearance = appearance;
    }

    public double Hue { get; }
    public MistyAppearance Appearance { get; }

    public MistyRgba Color(MistyThemedColor token) => token.Resolve(Hue, Appearance);

    /// <summary>The fill of a glass grade, before blur.</summary>
    public MistyRgba GlassFill(MistyGlassGrade grade)
    {
        bool dark = Appearance == MistyAppearance.Dark;
        return new MistyOklch(dark ? MistyGlass.LightnessDark : MistyGlass.Lightness,
            dark ? MistyGlass.ChromaDark : MistyGlass.Chroma, 0.0, MistyGlass.Alpha(grade, Appearance), true).Resolve(Hue);
    }

    public MistyRgba Sky => Color(MistyColorTokens.Sky);
    public MistyRgba SkyHigh => Color(MistyColorTokens.SkyHigh);
    public MistyRgba Aurora1 => Color(MistyColorTokens.Aurora1);
    public MistyRgba Aurora2 => Color(MistyColorTokens.Aurora2);
    public MistyRgba Aurora3 => Color(MistyColorTokens.Aurora3);
    public MistyRgba Ink90 => Color(MistyColorTokens.Ink90);
    public MistyRgba Ink70 => Color(MistyColorTokens.Ink70);
    public MistyRgba Ink50 => Color(MistyColorTokens.Ink50);
    public MistyRgba Ink30 => Color(MistyColorTokens.Ink30);
    public MistyRgba Ink10 => Color(MistyColorTokens.Ink10);
    public MistyRgba Ink06 => Color(MistyColorTokens.Ink06);
    public MistyRgba Accent => Color(MistyColorTokens.Accent);
    public MistyRgba AccentHover => Color(MistyColorTokens.AccentHover);
    public MistyRgba AccentPress => Color(MistyColorTokens.AccentPress);
    public MistyRgba AccentText => Color(MistyColorTokens.AccentText);
    public MistyRgba AccentSoft => Color(MistyColorTokens.AccentSoft);
    public MistyRgba OnAccent => Color(MistyColorTokens.OnAccent);
    public MistyRgba Success => Color(MistyColorTokens.Success);
    public MistyRgba Warning => Color(MistyColorTokens.Warning);
