/// <summary>Fluid type sizes from the window's width in effective pixels.</summary>
public static class MistyType
{
    public static double Display(double windowWidth) => Math.Clamp(windowWidth * 0.066, 52.0, 92.0);
    public static double H1(double windowWidth) => Math.Clamp(windowWidth * 0.046, 38.4, 60.0);
    public static double H2(double windowWidth) => Math.Clamp(windowWidth * 0.034, 30.4, 44.0);
    public static double H3(double windowWidth) => Math.Clamp(windowWidth * 0.02, 20.8, 24.0);
    public static double Lede(double windowWidth) => Math.Clamp(windowWidth * 0.015, 17.0, 19.0);

    /// <summary>The longest line of running text, in characters.</summary>
    public const int Measure = 68;
}

/// <summary>Page widths, fluid spacing and window classes in effective pixels.</summary>
public static class MistyLayout
{
    public const double Page = 1200.0;
    public const double PageDocs = 1312.0;
    public const double Reading = 704.0;
    public const double NavHeight = 72.0;
    public static double Gutter(double windowWidth) => Math.Clamp(windowWidth * 0.04, 18.0, 32.0);
    public static double Section(double windowWidth) => Math.Clamp(windowWidth * 0.09, 64.0, 120.0);

    public static MistyWindowClass WindowClass(double width) => width switch
    {
        <= 380 => MistyWindowClass.Narrow,
        <= 767 => MistyWindowClass.Compact,
        <= 1023 => MistyWindowClass.Medium,
        <= 1179 => MistyWindowClass.Expanded,
        _ => MistyWindowClass.Wide,
    };
}

