    public static readonly MistyShadowLayer[] Level2Light = { new(0.0, 2.0, 6.0, 0.0, new(0.3, 0.04, 0.0, 0.06, true)), new(0.0, 22.0, 48.0, -24.0, new(0.3, 0.08, 0.0, 0.3, true)) };
