    public static readonly MistyShadowLayer[] Level3Light = { new(0.0, 8.0, 24.0, 0.0, new(0.3, 0.04, 0.0, 0.1, true)), new(0.0, 40.0, 80.0, -30.0, new(0.3, 0.1, 0.0, 0.38, true)) };
    public static readonly MistyShadowLayer[] Level3Dark = { new(0.0, 8.0, 24.0, 0.0, new(0.0, 0.0, 0.0, 0.35, false)), new(0.0, 44.0, 84.0, -28.0, new(0.0, 0.0, 0.0, 0.78, false)) };

    public static MistyShadowLayer[] Layers(int level, MistyAppearance appearance)
    {
        bool dark = appearance == MistyAppearance.Dark;
        return level switch
        {
            1 => dark ? Level1Dark : Level1Light,
            2 => dark ? Level2Dark : Level2Light,
            3 => dark ? Level3Dark : Level3Light,
            _ => Array.Empty<MistyShadowLayer>(),
        };
    }
}

